/**
 * Superset topology for Stoa's read-only fleet dashboard.
 *
 * Required-now fields are normalized from `maw census --json` (#380) and are the
 * v1 source of truth. Display-census SpaceReport fields are optional/nullable so
 * they can be populated later without changing consumer code or the topology
 * contract.
 */
export type StoaFleetTopology = {
  /** Required-now: primary v1 oracle rows from `maw census --json`. */
  oracles: StoaCensusOracle[];

  /**
   * Optional-future: display-census SpaceReport `ts` when that feed is joined.
   * Nullable means the board has only the primary maw census source available.
   */
  displayCensusTs?: number | null;

  /** Optional-future: oracle labels by space/display from display-census. */
  fleet?: StoaDisplayCensusFleetRow[] | null;

  /** Optional-future: per-window global pixel frames from display-census. */
  windows?: StoaDisplayCensusWindow[] | null;

  /** Optional-future: per-space visibility/focus from display-census. */
  spaces?: StoaDisplayCensusSpace[] | null;

  /** Optional-future: display frames from display-census. */
  displays?: StoaDisplayCensusDisplay[] | null;
};

/**
 * Required-now `maw census --json` oracle row.
 *
 * TODO-confirm-with-maw-rs (#380): the live schema was not reachable while this
 * type was authored, so these fields model the required best-effort contract:
 * oracle handle, session/pane identifiers, host/machine, and status.
 */
export type StoaCensusOracle = {
  /** Oracle handle, e.g. the maw oracle name shown on the board tile. */
  oracle: string;

  /** Required tmux/session identifier from maw census. */
  sessionId: string;

  /** Required tmux pane identifier from maw census. */
  paneId: string;

  /** Required host or machine identity; normalized as `machine` for consumers. */
  machine: string;

  /** Required lifecycle/readiness status from maw census. */
  status: StoaOracleStatus;
};

/** Known Stoa statuses plus forward-compatible strings from maw-rs. */
export type StoaOracleStatus =
  | "starting"
  | "idle"
  | "busy"
  | "ready"
  | "sleeping"
  | "offline"
  | "error"
  | "unknown"
  | (string & Record<never, never>);

/** Global pixel rectangle, preserving display-census/window-arranger coordinates. */
export type StoaGlobalPixelFrame = {
  x: number;
  y: number;
  w: number;
  h: number;
};

/** Optional-future display-census fleet row: title is the oracle label. */
export type StoaDisplayCensusFleetRow = {
  title: string;
  space: number;
  display: number;
  focus: boolean;
};

/** Optional-future display-census window row with global pixel geometry. */
export type StoaDisplayCensusWindow = {
  id: number;
  app: string;

  /**
   * TODO(redaction): display-census window titles can expose work content and
   * must be redacted before this value reaches any board UI renderer.
   */
  title: string;

  /** Global screen pixel frame. Nullable for legacy or not-yet-populated rows. */
  frame: StoaGlobalPixelFrame | null;

  /** Optional pin-enforcement state from display-census/window-arranger. */
  pinned?: boolean | null;
};

/** Optional-future display-census space row. */
export type StoaDisplayCensusSpace = {
  index: number;
  display: number;
  isVisible: boolean;
  hasFocus: boolean;
};

/** Optional-future display-census display row used to resolve pixel frames. */
export type StoaDisplayCensusDisplay = {
  index: number;
  name?: string | null;
  frame?: StoaGlobalPixelFrame | null;
};
EOF

cat > docs/census-schema.md <<'EOF'
# Census topology schema

`src/types/census.ts` defines one consumer-facing topology type:
`StoaFleetTopology`. Its required source is `maw census --json` (#380); its
future display-census fields are optional and nullable.

## Required-now mapping from `maw census --json` (#380)

Issue #380's live JSON schema was not reachable from this worktree, so the v1
required row is intentionally best-effort and marked `TODO-confirm-with-maw-rs`
in the type file. The board normalizes the required `maw census --json` fields
into `StoaCensusOracle` like this:

| #380 / maw census concept | `StoaCensusOracle` field | Required today |
| --- | --- | --- |
| oracle handle | `oracle` | yes |
| session id/name | `sessionId` | yes |
| pane id | `paneId` | yes |
| host or machine identity | `machine` | yes |
| lifecycle/readiness status | `status` | yes |

If #380 lands a different spelling or a composite session/pane value, that
translation should happen at ingest. Consumers should keep reading the normalized
fields above.

## Optional display-census pixel fields

Display-census `SpaceReport` data is not required for the v1 maw census source.
These fields on `StoaFleetTopology` are therefore optional and nullable:

- `displayCensusTs?: number | null`
- `fleet?: StoaDisplayCensusFleetRow[] | null` — oracle labels by
  `title`, `space`, `display`, and `focus`.
- `windows?: StoaDisplayCensusWindow[] | null` — window `id`, `app`, redaction-
  sensitive `title`, optional global-pixel `frame`, and optional `pinned` state.
- `spaces?: StoaDisplayCensusSpace[] | null` — space index, display index,
  visibility, and focus.
- `displays?: StoaDisplayCensusDisplay[] | null` — display index plus nullable
  name/frame metadata for pixel-frame resolution.

Window frames are stored in global pixel coordinates so a later topology tile can
render display → spaces → window frames without throwing away window-arranger
layout data.

## Why display-census can slot in later without rewrites

Consumers only need to depend on `StoaFleetTopology` now: the required oracle
rows are stable for the maw census source, while display-census data already has
reserved optional fields in the same topology object. When display-census is
joined later, producers can begin filling `fleet`, `windows`, `spaces`, and
`displays`; consumers that do not need px geometry keep working from `oracles`,
and consumers that do need it can feature-detect non-null optional arrays instead
of migrating to a second schema.
EOF
