import type { StoaCensusOracle, StoaFleetTopology } from "../types/census";

export type CensusWireV1 = {
  schema: string;
  displays: CensusWireDisplay[];
};

type CensusWireDisplay = {
  name: string;
  spaces: CensusWireSpace[];
};

type CensusWireSpace = {
  name: string;
  oracles: CensusWireOracle[];
};

type CensusWireOracle = {
  oracle: string;
  session?: string;
  pane?: string;
  modelTier: string;
  status: StoaCensusOracle["status"];
  idleSec?: number;
  annotation: string;
  pinned: boolean;
};

export type CensusLoadMode = "auto" | "real" | "fixture";
export const CENSUS_LOADING_MODE = "auto-with-fixture-fallback" as const;

const fixtureWireUrl = new URL("./census-wire-v1.fixture.json", import.meta.url);

export function censusWireToTopology(wire: CensusWireV1): StoaFleetTopology {
  if (wire.schema !== "maw.census.v1") {
    throw new Error(`unsupported maw census schema: ${wire.schema}`);
  }

  return {
    spaces: wire.displays.flatMap((display, displayIndex) =>
      display.spaces.map((space, spaceIndex) => ({
        // Wire display/space names are human labels, so Stoa uses deterministic
        // array positions as numeric join coordinates for display-census later.
        display: displayIndex,
        space: spaceIndex,
        oracles: space.oracles.map(wireOracleToTopologyOracle),
      })),
    ),
    pins: null,
    displayCensusTs: null,
    fleet: null,
    windows: null,
    displayCensusSpaces: null,
    displays: null,
  };
}

export async function loadCensusTopology(mode: CensusLoadMode = censusLoadMode()): Promise<StoaFleetTopology> {
  if (mode === "fixture") return censusWireToTopology(await loadFixtureWire());
  if (mode === "real") return censusWireToTopology(await loadRealWire());

  try {
    return censusWireToTopology(await loadRealWire());
  } catch (error) {
    console.warn(`maw census --json unavailable; using fixture: ${errorMessage(error)}`);
    return censusWireToTopology(await loadFixtureWire());
  }
}

function wireOracleToTopologyOracle(oracle: CensusWireOracle): StoaCensusOracle {
  return {
    oracle: oracle.oracle,
    session: oracle.session,
    pane: oracle.pane,
    model_tier: oracle.modelTier,
    status: oracle.status,
    idle_sec: oracle.idleSec,
    annotation: oracle.annotation,
    pinned: oracle.pinned,
  };
}

function censusLoadMode(): CensusLoadMode {
  const configured = process.env.MAW_SERVE_CENSUS_MODE;
  if (configured === "fixture" || configured === "real") return configured;
  return "auto";
}

async function loadFixtureWire(): Promise<CensusWireV1> {
  return JSON.parse(await Bun.file(fixtureWireUrl).text()) as CensusWireV1;
}

async function loadRealWire(): Promise<CensusWireV1> {
  const proc = Bun.spawn(["maw", "census", "--json"], { stdout: "pipe", stderr: "pipe" });
  const stdout = await new Response(proc.stdout).text();
  const stderr = await new Response(proc.stderr).text();
  const exitCode = await proc.exited;

  if (exitCode !== 0) {
    throw new Error(`maw census --json exited ${exitCode}: ${stderr.trim() || "no stderr"}`);
  }

  try {
    return JSON.parse(stdout) as CensusWireV1;
  } catch (error) {
    throw new Error(`maw census --json returned invalid JSON: ${errorMessage(error)}`);
  }
}

function errorMessage(error: unknown): string {
  return error instanceof Error ? error.message : String(error);
}

--- docs ---
# Census topology schema

`src/types/census.ts` defines one consumer-facing topology type:
`StoaFleetTopology`. Its required source is the final `maw census --json` #382
schema; future display-census fields remain optional and nullable.

## Required-now mapping from final `maw census --json` (#382)

The confirmed #382 census shape is grouped by display and space. Stoa keeps that
shape directly as required `StoaFleetTopology.spaces`:

| #382 / maw census concept | Stoa field | Required today |
| --- | --- | --- |
| display index | `spaces[].display` | yes |
| space index | `spaces[].space` | yes |
| oracle rows on that space | `spaces[].oracles` | yes |
| oracle handle | `spaces[].oracles[].oracle` | yes |
| session id/name | `spaces[].oracles[].session` | optional |
| pane id | `spaces[].oracles[].pane` | optional |
| model tier | `spaces[].oracles[].model_tier` | yes |
| lifecycle/readiness status | `spaces[].oracles[].status` | yes |
| idle age in seconds | `spaces[].oracles[].idle_sec` | optional |
| safe oracle annotation | `spaces[].oracles[].annotation` | yes |
| pin state for this location | `spaces[].oracles[].pinned` | yes |

The old flat `oracles` array is intentionally gone. Consumers should walk
`spaces[]` first, then each space's `oracles[]`.

## Pins from window-arranger

`StoaFleetTopology.pins?: StoaCensusPin[] | null` records pins from
window-arranger's `pins.json`: `{ display, space, oracle, note? }`. The field is
optional/nullable because `pins.json` may not exist or may be unavailable on a
host; when the source is available and has no pins, producers should send `[]`.

## Optional display-census pixel fields

Display-census `SpaceReport` data is not required for the v1 maw census source.
These fields on `StoaFleetTopology` are therefore optional and nullable:

- `displayCensusTs?: number | null`
- `fleet?: StoaDisplayCensusFleetRow[] | null` — oracle labels by
  `title`, `space`, `display`, and `focus`, with optional pass-through metadata
  when display-census provides it.
- `windows?: StoaDisplayCensusWindow[] | null` — window `id`, `app`, structurally
  redacted `title`, optional space/display/focus indexes, optional global-pixel
  `frame`, and optional `pinned` state.
- `displayCensusSpaces?: StoaDisplayCensusSpace[] | null` — display-census
  `spaces[]` visibility/focus/pin components, named distinctly because top-level
  `spaces` is now the required #382 census grouping.
- `displays?: StoaDisplayCensusDisplay[] | null` — display index plus nullable
  name/frame metadata for pixel-frame resolution.

Window frames are stored in global pixel coordinates so a later topology tile can
render display → spaces → window frames without throwing away window-arranger
layout data.

`windows[].title` is a branded `RedactedTitle`, not a plain `string`. A raw
display-census title cannot satisfy the type, so a renderer cannot receive
unredacted window titles unless a future redaction filter explicitly mints the
opaque value.

## Display-census join design

The census source is grouped by `(display, space)`, and display-census enrichment
also carries `(display, space)` or display indexes on `fleet`, `windows`,
`displayCensusSpaces`, and `displays`. The topology/reflection tile can therefore
join the required census rows to optional pixel data by `(display, space)`:
census supplies oracle truth, display-census supplies visibility/focus and global
pixel frames, and consumers keep using this same superset type as enrichment is
added.

--- test ---
import { expect, test } from "bun:test";
import { handleRequest } from "../server";
import { censusWireToTopology } from "../src/census/topology";
import type { CensusWireV1 } from "../src/census/topology";
import type { StoaFleetTopology } from "../src/types/census";

const fixtureUrl = new URL("../src/census/census-wire-v1.fixture.json", import.meta.url);

async function loadWireFixture(): Promise<CensusWireV1> {
  return JSON.parse(await Bun.file(fixtureUrl).text()) as CensusWireV1;
}

test("censusWireToTopology adapts maw.census.v1 wire shape", async () => {
  const body = censusWireToTopology(await loadWireFixture());

  expect(body.spaces).toHaveLength(2);
  expect(body.spaces[0].display).toBe(0);
  expect(body.spaces[0].space).toBe(0);
  expect(body.spaces[1].display).toBe(0);
  expect(body.spaces[1].space).toBe(1);

  const oracle = body.spaces[0].oracles[0];
  expect(oracle.oracle).toBe("m5");
  expect(oracle.session).toBe("maw-serve");
  expect(oracle.pane).toBe("%42");
  expect(oracle.model_tier).toBe("frontier");
  expect(oracle.idle_sec).toBe(0);
  expect(oracle.status).toBe("busy");
  expect(oracle.annotation).toBe("building Stoa census route");
  expect(oracle.pinned).toBe(false);
  expect("machine" in oracle).toBe(false);
  expectDisplayCensusFieldsNull(body);
});

test("censusWireToTopology rejects unsupported schema versions", () => {
  expect(() => censusWireToTopology({ schema: "maw.census.v0", displays: [] })).toThrow(
    "unsupported maw census schema",
  );
});

test("GET /api/agora/census returns fixture-backed StoaFleetTopology", async () => {
  const previousMode = process.env.MAW_SERVE_CENSUS_MODE;
  process.env.MAW_SERVE_CENSUS_MODE = "fixture";

  try {
    const res = await handleRequest(new Request("http://localhost/api/agora/census"));
    expect(res.status).toBe(200);

    const body = (await res.json()) as StoaFleetTopology;
    expect(body.spaces.length).toBeGreaterThan(0);
    expect(typeof body.spaces[0].display).toBe("number");
    expect(typeof body.spaces[0].space).toBe("number");
    expect(body.spaces[0].oracles[0].model_tier).toBe("frontier");
    expectDisplayCensusFieldsNull(body);
  } finally {
    if (previousMode === undefined) delete process.env.MAW_SERVE_CENSUS_MODE;
    else process.env.MAW_SERVE_CENSUS_MODE = previousMode;
  }
});

function expectDisplayCensusFieldsNull(body: StoaFleetTopology) {
  expect(body.pins).toBeNull();
  expect(body.displayCensusTs).toBeNull();
  expect(body.fleet).toBeNull();
  expect(body.windows).toBeNull();
  expect(body.displayCensusSpaces).toBeNull();
  expect(body.displays).toBeNull();
}

