#!/bin/bash
# oracle-lineage hourly auto-scan → build → deploy → commit (append-only).
# Writes a new vN dataset ONLY when the family structure changed
# (new/gone repos, origin/parent/awakened/canonical flips) — commit-count
# churn alone does not spam versions.
# pm2: pm2 start cron.sh --name oracle-lineage-cron --cron-restart="7 * * * *" --no-autorestart
set -euo pipefail
export PATH="$HOME/.bun/bin:/opt/homebrew/bin:/usr/local/bin:$PATH"

LINEAGE="$(cd "$(dirname "$0")" && pwd)"
REPO="$(cd "$LINEAGE/../.." && pwd)"

cd "$LINEAGE"
bun hey-graph.ts --deploy   # hey ledger moves hourly — snapshot + ship every run
bun scan.ts --all --if-changed

cd "$REPO"
if [ -n "$(git status --porcelain registry/lineage registry/bud-tree.html registry/oracle-family.html)" ]; then
  git add registry/lineage registry/bud-tree.html registry/oracle-family.html
  git commit -m "data(lineage): auto-scan $(date +%F_%H%M) [cron]

Co-Authored-By: Claude Opus 4.8 <noreply@anthropic.com>" || true
  git push || true
  echo "✅ committed + pushed"
else
  echo "clean — nothing to commit"
fi

